#include "fs_internal.h"
#include <errno.h>
#include <string.h>
#include <stdlib.h>
int dir_lookup(uint32_t d,const char *name,uint32_t *out){ inode_t x; if(inode_read(d,&x)<0)return -EIO; if(x.type!=INODE_DIR)return -ENOTDIR; for(uint32_t l=0;l<x.block_count;l++){ int b=map_block(&x,l,0); if(b<0)continue; dir_entry_t e[BLOCK_SIZE/sizeof(dir_entry_t)]; disk_read((uint32_t)b,e); for(unsigned j=0;j<16;j++)if(e[j].inode_no && strncmp(e[j].name,name,28)==0){*out=e[j].inode_no;return 0;}} return -ENOENT; }
int dir_add(uint32_t d,const char *name,uint32_t ino){ if(strlen(name)>MAX_NAME)return -ENAMETOOLONG; uint32_t tmp; int r=dir_lookup(d,name,&tmp); if(r==0)return -EEXIST; inode_t x; inode_read(d,&x); for(uint32_t l=0;l<=x.block_count;l++){ int b=map_block(&x,l,1); if(b<0)return b; dir_entry_t e[16]; disk_read((uint32_t)b,e); for(int j=0;j<16;j++)if(!e[j].inode_no){ memset(&e[j],0,sizeof e[j]); strncpy(e[j].name,name,28);e[j].inode_no=ino;disk_write((uint32_t)b,e);x.size+=sizeof(dir_entry_t);inode_write(d,&x);return 0; }} return -ENOSPC; }
int dir_remove(uint32_t d,const char *name){ inode_t x;inode_read(d,&x);for(uint32_t l=0;l<x.block_count;l++){int b=map_block(&x,l,0);if(b<0)continue;dir_entry_t e[16];disk_read((uint32_t)b,e);for(int j=0;j<16;j++)if(e[j].inode_no&&strncmp(e[j].name,name,28)==0){memset(&e[j],0,sizeof e[j]);disk_write((uint32_t)b,e);if(x.size>=32)x.size-=32;inode_write(d,&x);return 0;}}return -ENOENT;}
int resolve_path(const char *path,uint32_t cwd,uint32_t *out,uint32_t *parent,char *leaf){ if(!path||!*path)return -ENOENT; char tmp[MAX_PATH]; if(strlen(path)>=sizeof tmp)return -ENAMETOOLONG;strcpy(tmp,path);uint32_t cur=(path[0]=='/')?0:cwd, par=cur; char *save=NULL,*tok=strtok_r(tmp,"/",&save); if(!tok){*out=0;if(parent)*parent=0;if(leaf)leaf[0]=0;return 0;} char last[29]=""; while(tok){ if(!strcmp(tok,".")){tok=strtok_r(NULL,"/",&save);continue;} if(!strcmp(tok,"..")){uint32_t up;if(dir_lookup(cur,"..",&up)==0)cur=up;tok=strtok_r(NULL,"/",&save);continue;} if(strlen(tok)>28)return -ENAMETOOLONG; par=cur;strncpy(last,tok,28);last[28]=0;uint32_t next;int r=dir_lookup(cur,tok,&next);if(r<0){if(!strtok_r(NULL,"/",&save)){if(parent)*parent=par;if(leaf)strcpy(leaf,last);return r;}return r;}cur=next;tok=strtok_r(NULL,"/",&save); }*out=cur;if(parent)*parent=par;if(leaf)strcpy(leaf,last);return 0; }
